package io.github.capozziv.digitalbanking.statement.bootstrap.web

import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import org.springframework.boot.test.web.server.LocalServerPort
import tools.jackson.databind.JsonNode

/** The OpenAPI contract generated by springdoc documents the statement operation and its errors. */
class OpenApiIntegrationTest : StatementWebIntegrationTest() {
    @LocalServerPort
    private var port: Int = 0

    private val docs: JsonNode by lazy {
        val response = ApiClient(port).get("/v3/api-docs") // open: no token
        assertThat(response.status).describedAs(response.rawBody).isEqualTo(200)
        response.body!!
    }

    private val statement: JsonNode by lazy { docs.get("paths").get("/accounts/{accountId}/statement").get("get") }

    @Test
    fun `the contract has exactly the statement operation`() {
        assertThat(docs.get("paths").propertyNames()).containsExactly("/accounts/{accountId}/statement")
    }

    @Test
    fun `the operation documents its parameters`() {
        val parameters = statement.get("parameters").associateBy { it.get("name").asString() }

        assertThat(parameters.getValue("accountId").get("required").asBoolean()).isTrue()
        assertThat(parameters.getValue("cursor").get("required").asBoolean()).isFalse()
        assertThat(parameters.getValue("limit").get("required").asBoolean()).isFalse()
    }

    @Test
    fun `the operation documents 200, 400 and 404 with Problem Details for the errors`() {
        val responses = statement.get("responses")

        assertThat(responses.get("200").get("content").get("application/json")).isNotNull()
        assertThat(responses.get("400").get("description").asString()).contains("/problems/validation-error")
        assertThat(responses.get("404").get("description").asString()).contains("/problems/account-not-found")
        for (status in listOf("400", "404", "500")) {
            val schema =
                responses
                    .get(status)
                    .get("content")
                    .get("application/problem+json")
                    .get("schema")
            assertThat(schema.get("\$ref").asString()).describedAs(status).endsWith("/ProblemDetail")
        }
    }

    @Test
    fun `the contract declares bearerAuth for every request and documents 401`() {
        val scheme = docs.get("components").get("securitySchemes").get("bearerAuth")

        assertThat(scheme.get("type").asString()).isEqualTo("http")
        assertThat(scheme.get("scheme").asString()).isEqualTo("bearer")
        assertThat(scheme.get("bearerFormat").asString()).isEqualTo("JWT")
        assertThat(docs.get("security").get(0).has("bearerAuth")).isTrue()
        assertThat(
            statement
                .get("responses")
                .get("401")
                .get("description")
                .asString(),
        ).contains("/problems/unauthorized")
    }

    @Test
    fun `the schemas carry the statement fields`() {
        val schemas = docs.get("components").get("schemas")

        assertThat(schemas.get("StatementDTO").get("properties").propertyNames()).contains("accountId", "entries", "nextCursor")
        assertThat(schemas.get("StatementEntryDTO").get("properties").propertyNames())
            .contains("entryId", "sequence", "kind", "amount", "balanceAfter", "description", "createdAt")
    }
}
